components.css:
.ds-preview{font:400 18px/1.55 var(--sans);background:var(--blue);color:var(--white)}.ds-preview :where(a){color:inherit;text-underline-offset:5px}.ds-preview svg{display:block}.ds-preview :where(a):focus-visible{outline:3px solid currentColor;outline-offset:7px}
.ds-wrap{max-width:1440px;margin-inline:auto;padding-inline:var(--gutter)}
.ds-site-header{height:112px;display:flex;justify-content:space-between;align-items:center}
.ds-wordmark{font:400 38px/1 var(--serif);letter-spacing:-.03em;text-decoration:none}
.ds-wordmark span{color:var(--amber)}
.ds-preview nav{display:flex;align-items:center;gap:40px}
.ds-preview nav a{text-decoration:none;font-size:15px}
.ds-about-link{padding:12px 0}
.ds-about-link:hover{text-decoration:underline}
.ds-github-link{display:flex;align-items:center;gap:12px;border:1px solid rgb(255 255 255 / .5);padding:12px 18px;border-radius:6px;min-height:48px}
.ds-github-link:hover{background:var(--white);color:var(--blue)}
@media(max-width:1050px){.ds-site-header{height:92px}}
@media(max-width:700px){.ds-site-header{height:88px}
.ds-wordmark{font-size:32px}
.ds-preview nav{gap:20px}
.ds-about-link{display:none}
.ds-github-link{padding:10px 12px}}
@media(prefers-reduced-motion:reduce){.ds-preview *,.ds-preview *::before,.ds-preview *::after{transition:none!important}}

.ds-preview{font:400 18px/1.55 var(--sans);background:var(--white);color:var(--blue)}.ds-preview :where(a){color:inherit;text-underline-offset:5px}.ds-preview svg{display:block}.ds-preview :where(a):focus-visible{outline:3px solid currentColor;outline-offset:7px}
.ds-chapter-strip{background:var(--pink);color:var(--white);display:flex;align-items:center;justify-content:center;gap:clamp(18px,3vw,48px);padding:25px var(--gutter);font:400 clamp(24px,2.2vw,31px)/1.2 var(--serif)}
.ds-chapter-strip svg{flex:none;width:25px;height:25px;fill:none;stroke:currentColor;stroke-width:1.5}
.ds-chapter-strip span{white-space:nowrap}
@media(max-width:1050px){.ds-chapter-strip{gap:18px;font-size:24px}
.ds-chapter-strip span:last-child,.ds-chapter-strip svg:last-of-type{display:none}}
@media(max-width:700px){.ds-chapter-strip{justify-content:space-between;padding-block:22px;gap:15px;font-size:24px}
.ds-chapter-strip span:nth-of-type(2){display:none}
.ds-chapter-strip svg:first-of-type{width:24px}}
@media(max-width:700px){.ds-chapter-strip{justify-content:center}
.ds-chapter-strip svg{display:none}}
@media(prefers-reduced-motion:reduce){.ds-preview *,.ds-preview *::before,.ds-preview *::after{transition:none!important}}

.ds-preview{font:400 18px/1.55 var(--sans);background:var(--white);color:var(--blue)}.ds-preview :where(a){color:inherit;text-underline-offset:5px}.ds-preview svg{display:block}.ds-preview :where(a):focus-visible{outline:3px solid currentColor;outline-offset:7px}
.ds-spread{display:grid;grid-template-columns:1fr 1fr}
.ds-spread-human{background:var(--pink);color:var(--white)}
.ds-spread-agent{background:var(--amber);color:var(--blue)}
.ds-spread-inner{max-width:720px;margin-left:auto;padding:62px var(--gutter) 48px}
.ds-spread-agent .ds-spread-inner{margin-left:0;margin-right:auto}
.ds-chapter-icon{height:50px;width:50px;fill:none;stroke:currentColor;stroke-width:1.8;margin-bottom:35px}
.ds-spread h2{font:400 clamp(38px,4.1vw,58px)/1.05 var(--serif);letter-spacing:-.025em;margin:0 0 28px}
.ds-spread p{font-size:24px;line-height:1.5;margin:0 0 40px}
.ds-spread-end{display:block;border-top:1px solid currentColor;padding-top:20px;font-size:20px;font-weight:700;line-height:1.4}
@media(max-width:1050px){.ds-spread-inner{padding-block:48px}
.ds-spread p{font-size:24px}}
@media(max-width:700px){.ds-spread{grid-template-columns:1fr}
.ds-spread-inner{padding:42px var(--gutter)}
.ds-chapter-icon{margin-bottom:25px}
.ds-spread h2{font-size:44px}
.ds-spread p{font-size:24px}
.ds-spread-end{font-size:20px}}
@media(max-width:1050px){.ds-spread{grid-template-columns:1fr}
.ds-spread-inner{max-width:none;margin-inline:0}
.ds-spread-agent .ds-spread-inner{margin-inline:0}}
@media(prefers-reduced-motion:reduce){.ds-preview *,.ds-preview *::before,.ds-preview *::after{transition:none!important}}
